=$pkgs[$j];$rk=@($writes|Where-Object package -ceq $r|ForEach-Object{$_.target_path+'|'+$_.pk_column+'|'+$_.pk_value});A (@($writes|Where-Object package -ceq $l|ForEach-Object{$_.target_path+'|'+$_.pk_column+'|'+$_.pk_value}|Where-Object{$_ -cin $rk}).Count-eq0) "cross-package write overlap: $l/$r";$rp=@($payloads|Where-Object package -ceq $r|ForEach-Object{$_.target_path});A (@($payloads|Where-Object package -ceq $l|ForEach-Object{$_.target_path}|Where-Object{$_ -cin $rp}).Count-eq0) "cross-package payload overlap: $l/$r"}};Record 'bundle_shape' 'passed' '1057 unique PKs; 15 payloads; 20 tables; 11 guards; cross-package intersections=0'
$postPath=Join-Path $PrepRoot 'expected-candidate-20-table-posthashes.csv';A ((Get-HashValue $postPath)-ceq '78956df9394146d39ded5e6e0740157e4ccd9cc50e44699ec6f8b8eca0ea1394')'candidate posthash manifest hash differs';$post=@(Import-Csv -LiteralPath $postPath -Encoding UTF8);A ($post.Count-eq20)'candidate posthash rows differ';$postMap=@{};foreach($e in $post){A (-not$postMap.ContainsKey([string]$e.target_path)) "duplicate candidate posthash: $($e.target_path)";$postMap[[string]$e.target_path]=[string]$e.candidate_postmerge_sha256};$candidateParts=foreach($e in($formal|Sort-Object relative_path)){$h=[string]$e.sha256;if($postMap.ContainsKey([string]$e.relative_path)){$h=$postMap[[string]$e.relative_path]};[string]$e.relative_path+'|'+$h};$candidate=TH($candidateParts-join[char]10);A ($candidate-ceq$ExpectedCandidate)'candidate posthash reconstruction differs';Record 'candidate_contract' 'passed' "posthash_rows=20; aggregate=$candidate; checks=$ExpectedChecks"
$bindings=@(Import-Csv -LiteralPath (Join-Path $PrepRoot 'upstream-bindings.csv') -Encoding UTF8);A ($bindings.Count-eq3)'upstream bindings rows differ';$sourceHashCache=@{};foreach($b in($bindings|Sort-Object{[int]$_.package_order})){$data=C $SourceRoot ([string]$b.data_signoff_path);A ((Get-HashValue $data)-ceq[string]$b.data_signoff_sha256) "data signoff hash differs: $($b.package)";$dataRows=@(Import-Csv -LiteralPath $data -Encoding UTF8);A ($dataRows.Count-eq[int]$b.data_signoff_rows) "data signoff rows differ: $($b.package)";A (@($dataRows.signoff_row_id|Sort-Object -Unique).Count-eq$dataRows.Count) "data signoff ids not unique: $($b.package)";A (@($dataRows|Where-Object verdict -cne 'accept').Count-eq0) "data signoff verdict differs: $($b.package)";A (@($dataRows|Where-Object formal_baseline_aggregate_sha256 -cne $ExpectedFormal).Count-eq0) "data signoff baseline differs: $($b.package)";$life=@($dataRows|Where-Object binding_kind -ceq 'lifecycle_pk_write');$files=@($dataRows|Where-Object binding_kind -cne 'lifecycle_pk_write');A ($life.Count+$files.Count-eq$dataRows.Count) "data signoff kinds differ: $($b.package)";A (@($life|ForEach-Object{$_.target_path+'|'+$_.pk_column+'|'+$_.pk_value}|Sort-Object -Unique).Count-eq$life.Count) "data lifecycle targets duplicate: $($b.package)";foreach($row in $dataRows){$sp=C $SourceRoot ([string]$row.source_path);if(-not$sourceHashCache.ContainsKey($sp)){$sourceHashCache[$sp]=@((Get-HashValue $sp),(Get-Item -LiteralPath $sp).Length)};A ($sourceHashCache[$sp][0]-ceq[string]$row.source_sha256) "data source hash differs: $($row.signoff_row_id)";A ([int64]$sourceHashCache[$sp][1]-eq[int64]$row.source_bytes) "data source bytes differ: $($row.signoff_row_id)"};$prepManifestPath=C $SourceRoot (([string]$b.upstream_prep_path).TrimEnd('/')+'/manifest.csv');A ((Get-HashValue $prepManifestPath)-ceq[string]$b.upstream_prep_manifest_sha256) "upstream prep manifest differs: $($b.package)";$upRoot=Split-Path -Parent $prepManifestPath;$upManifest=@(Import-Csv -LiteralPath $prepManifestPath -Encoding UTF8);$upAgg=PA $upRoot $upManifest;A ($upAgg-ceq[string]$b.upstream_prep_aggregate_sha256) "upstream prep aggregate differs: $($b.package)";$tx=C $SourceRoot ([string]$b.transaction_signoff_path);A ((Get-HashValue $tx)-ceq[string]$b.transaction_signoff_sha256) "transaction signoff hash differs: $($b.package)";$txRows=@(Import-Csv -LiteralPath $tx -Encoding UTF8);A ($txRows.Count-eq1) "transaction signoff rows differ: $($b.package)";A ([string]$txRows[0].verdict-ceq 'accept') "transaction signoff verdict differs: $($b.package)";A ([string]$txRows[0].ready_for_formal_execution-ceq 'true') "transaction signoff readiness differs: $($b.package)";A ([string]$txRows[0].package_manifest_sha256-ceq[string]$b.upstream_prep_manifest_sha256) "transaction manifest binding differs: $($b.package)";A ([string]$txRows[0].package_aggregate_sha256-ceq[string]$b.upstream_prep_aggregate_sha256) "transaction aggregate binding differs: $($b.package)";A ([string]$txRows[0].formal_baseline_aggregate_sha256-ceq$ExpectedFormal) "transaction baseline differs: $($b.package)";Record ('upstream_'+$b.package) 'passed' ("data_rows="+$dataRows.Count+"; data_sha="+$b.data_signoff_sha256+"; tx_sha="+$b.transaction_signoff_sha256+"; prep_aggregate="+$upAgg)}
